function correctWord(word, dict) {
  // simple one-edit distance correction
  if (dict.has(word)) return word;
  // naive neighbor search: insert/delete/replace
  // (illustrative; real impl would be optimized)
  for (const w of dict) {
    if (levDistance(word, w) <= 1) return w;
